INSERT INTO public.bars (id, created_at, updated_at, name, location, lat, lon, type, points, experience, visited, visit_date, google_maps_link, tabelog_link, official_website, score, score_place, score_mingling, score_price) VALUES (1, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Tatsu Ichi', 'Shibuya, Center Gai', 35.660987, 139.697056, 'Standing Bar', 'A standing bar where it is easy to mingle with people. Quite cheap, no table charge.', 'Situated at the end of the main street "center gai", there is always a lot of foreigners there. Friendly Japanese staff. TV playing sports. Music. All kind of drinks and food also available. Payment must be done upon order at the table. Beer is 300yen. Can be kind of loud and smoky. Very easy to mingle with people. There is a live webcam you can access from their website, if you want to check the crowd.', true, '2017-07-07 22:00:00', 'https://www.google.com/maps/place/TASUICHI/@35.6599464,139.6966029,17z/data=!4m5!3m4!1s0x60188ca970e7aaab:0x8b912b8ebfe8bafe!8m2!3d35.6609271!4d139.6970106', 'https://tabelog.com/tokyo/A1303/A130301/13020555/', 'http://www.tasuichi.co.jp/', 2, 1, 3, 2);
INSERT INTO public.bars (id, created_at, updated_at, name, location, lat, lon, type, points, experience, visited, visit_date, google_maps_link, tabelog_link, official_website, score, score_place, score_mingling, score_price) VALUES (2, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Coins bar', 'Shibuya, Udagawacho', 35.662074, 139.697344, 'Bar', 'Everthing is 300 yen. No table charge.', 'B1F. Can be loud and smoky. Quite dark. Possible to mingle, especially if drinking at the main, big table, but people are not supposed to leave their seat and walk around. Complimentary small bowl of popcorn is given. Sometimes, there is a popular DJ event.', true, '2017-07-07 22:00:00', 'https://www.google.com/maps/place/Coins+Bar/@35.6620286,139.6950236,17z/data=!3m1!4b1!4m5!3m4!1s0x60188ca9415924a3:0xb1f01b371af5fcc4!8m2!3d35.6620243!4d139.6972123', 'https://tabelog.com/tokyo/A1303/A130301/13036298/', 'https://www.hotpepper.jp/strJ000011428/', 1, 1, 2, 2);
INSERT INTO public.bars (id, created_at, updated_at, name, location, lat, lon, type, points, experience, visited, visit_date, google_maps_link, tabelog_link, official_website, score, score_place, score_mingling, score_price) VALUES (3, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Hub', 'Shibuya, Dogenzaka', 35.658931, 139.697853, 'British Pub', 'Big chain of British pubs. No table charge.', 'B1F. One section for non smokers. Happy hours from 5pm to 7pm. Quite easy to walk around and mingle. TV shows some sports.', true, '2017-07-07 22:00:00', 'https://www.google.com/maps/place/HUB%E6%B8%8B%E8%B0%B7%E9%81%93%E7%8E%84%E5%9D%82%E5%BA%97/@35.6586675,139.6963393,17.25z/data=!4m5!3m4!1s0x60188ca9dbd8f065:0x74414b744e7f5174!8m2!3d35.6588625!4d139.6978816', 'https://tabelog.com/tokyo/A1303/A130301/13185353/', 'https://www.pub-hub.com/index.php/shop/detail/96', 1, 1, 2, 1);
INSERT INTO public.bars (id, created_at, updated_at, name, location, lat, lon, type, points, experience, visited, visit_date, google_maps_link, tabelog_link, official_website, score, score_place, score_mingling, score_price) VALUES (4, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Hub', 'Shibuya, Center Gai', 35.659906, 139.699935, 'British Pub', 'Big chain of British pubs. No table charge.', 'B1F. Happy hours from 5pm to 7pm. Quite easy to walk around and mingle. TV shows some sports. Popular and well situated, the place is quite crowded, usually with a lot of foreigners.', true, '2017-07-07 22:00:00', 'https://www.google.com/maps/place/HUB/@35.6598773,139.6977413,17z/data=!3m1!4b1!4m5!3m4!1s0x60188ca823a4c10f:0xd9a1a25ed54e0e6!8m2!3d35.659873!4d139.69993', 'https://tabelog.com/tokyo/A1303/A130301/13185646/', 'https://www.pub-hub.com/index.php/shop/detail/90', 1, 1, 2, 1);
INSERT INTO public.bars (id, created_at, updated_at, name, location, lat, lon, type, points, experience, visited, visit_date, google_maps_link, tabelog_link, official_website, score, score_place, score_mingling, score_price) VALUES (5, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Hub', 'Shibuya, Udagawacho', 35.662435, 139.698766, 'British Pub', 'Big chain of British pubs. No table charge.', 'B1F. One section for non smokers. Happy hours from 5pm to 7pm. Quite easy to walk around and mingle. TV shows some sports. Popular, the place is fairly crowded, usually with a lot of foreigners.', true, '2017-07-07 22:00:00', 'https://www.google.com/maps/place/HUB+Shibuya/@35.6624703,139.6965823,17z/data=!3m1!4b1!4m5!3m4!1s0x60188ca9207054cd:0x912d5501fd059fc1!8m2!3d35.662466!4d139.698771', 'https://tabelog.com/tokyo/A1303/A130301/13002059/', 'https://www.pub-hub.com/index.php/shop/detail/2', 2, 1, 2, 1);
INSERT INTO public.bars (id, created_at, updated_at, name, location, lat, lon, type, points, experience, visited, visit_date, google_maps_link, tabelog_link, official_website, score, score_place, score_mingling, score_price) VALUES (6, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Hub', 'Shibuya, Udagawacho', 35.66066, 139.698791, 'British Pub', 'Big chain of British pubs. No table charge.', 'B1F. Happy hours from 5pm to 7pm. Quite easy to walk around and mingle. TV shows some sports. Popular, the place is fairly crowded, usually with a lot of foreigners.', true, '2017-07-07 22:00:00', 'https://www.google.com/maps/place/HUB+Shibuya/@35.6624703,139.6965823,17z/data=!3m1!4b1!4m5!3m4!1s0x60188ca9207054cd:0x912d5501fd059fc1!8m2!3d35.662466!4d139.698771', 'https://tabelog.com/tokyo/A1303/A130301/13042468/', 'https://www.pub-hub.com/index.php/shop/detail/109', 1, 1, 2, 1);
INSERT INTO public.bars (id, created_at, updated_at, name, location, lat, lon, type, points, experience, visited, visit_date, google_maps_link, tabelog_link, official_website, score, score_place, score_mingling, score_price) VALUES (7, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Hobgoblin', 'Shibuya, Dogenzaka', 35.658331, 139.699608, 'British Pub', 'Small chain of British pubs. No table charge.', '3F. Nice pub, feeling better, more local, than the Hub, will be less crowded and not as easy to mingle.', true, '2017-07-07 22:00:00', 'https://www.google.com/maps/place/Hobgoblin+Shibuya+British+Pub/@35.6583003,139.6974463,17z/data=!3m1!4b1!4m5!3m4!1s0x60188b57c704df9d:0x45950055d352b895!8m2!3d35.658296!4d139.699635', 'https://tabelog.com/tokyo/A1303/A130301/13015858/', 'http://hobgoblin.jp/%E2%80%8B%E3%83%9B%E3%83%96%E3%82%B4%E3%83%96%E3%83%AA%E3%83%B3%E6%B8%8B%E8%B0%B7/', 1, 2, 1, 1);
INSERT INTO public.bars (id, created_at, updated_at, name, location, lat, lon, type, points, experience, visited, visit_date, google_maps_link, tabelog_link, official_website, score, score_place, score_mingling, score_price) VALUES (8, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'The Dubliners', 'Shibuya, Dogenzaka', 35.659216, 139.697948, 'Irish Pub', 'Nice pub with an open air section.', '2F. I really like that they have a covered terrace, opened all seasons. The place can be quite crowded, with lots of foreigners.', true, '2017-07-07 22:00:00', 'https://www.google.com/maps/place/THE+DUBLINERS''+IRISH+PUB+%E6%B8%8B%E8%B0%B7%E5%BA%97/@35.6592592,139.6957692,17z/data=!3m1!4b1!4m5!3m4!1s0x60188ca9c4cfffff:0x7cf08f7b4c365416!8m2!3d35.6592549!4d139.6979579', 'https://tabelog.com/tokyo/A1303/A130301/13025772/', 'http://www.dubliners.jp/shop.html', 2, 2, 1, 1);
INSERT INTO public.bars (id, created_at, updated_at, name, location, lat, lon, type, points, experience, visited, visit_date, google_maps_link, tabelog_link, official_website, score, score_place, score_mingling, score_price) VALUES (9, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Pres', 'Shibuya, Center Gai', 35.660836, 139.697885, 'Jazz Bar', 'Small, dark, peaceful bar with jazz music.', 'B1F. The place is very dark, with a big U-shape counter only. Nice bartender making nice cocktails. The crowd is mostly mature Japanese. There is a few hundreds yen for table charge.', true, '2017-07-07 22:00:00', 'https://www.google.com/maps/place/Pres+Jazz+Bar/@35.6602446,139.6967952,17.75z/data=!4m5!3m4!1s0x60188ca9a73db223:0x94724485461cf449!8m2!3d35.6608245!4d139.6979092', 'https://tabelog.com/tokyo/A1303/A130301/13171801/', 'http://tokyojazzsite.com/directory/listing/pres-jazz-bar', 1, 1, 1, 0);
INSERT INTO public.bars (id, created_at, updated_at, name, location, lat, lon, type, points, experience, visited, visit_date, google_maps_link, tabelog_link, official_website, score, score_place, score_mingling, score_price) VALUES (10, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Start bar', 'Shibuya, Sakuragaokacho', 35.656169, 139.701352, 'Bar', 'No table charge.', '3F. The place is quite nice, rather spacious, dark but clean and with tables next to the windows, and a large U-shape counter. Friendly bartender. On a Friday night, nobody was there around 9pm, and when I tried again around 11pm, a bunch of friends, young people, were playing a soccer video game on a PS4.', true, '2017-07-07 22:00:00', 'https://www.google.com/maps/place/Start+Bar/@35.65644,139.6987829,16.75z/data=!4m5!3m4!1s0x60188b575886aaab:0xcae17a169b9e55a6!8m2!3d35.65615!4d139.701309', 'https://tabelog.com/tokyo/A1303/A130301/13188833/', 'http://start-bar.com/', 1, 1, 1, 1);
INSERT INTO public.bars (id, created_at, updated_at, name, location, lat, lon, type, points, experience, visited, visit_date, google_maps_link, tabelog_link, official_website, score, score_place, score_mingling, score_price) VALUES (11, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'The Wine', 'Shibuya', 35.656348, 139.700879, 'Izakaya', 'Very cheap, and good wine. 500 yen table charge.', 'B1F. This is a nice little restaurant. Nice staff as well. It is OK to go there and just drink. The wine is good and very cheap, starting 180 yen a glass, or 800 yen for a bootle! But there is a 500 yen table charge (a fee each person must pay).', true, '2017-07-07 22:00:00', 'https://www.google.com/maps/place/The+Wine%EF%BC%88%E3%82%B6+%E3%83%AF%E3%82%A4%E3%83%B3%EF%BC%89+%E6%B8%8B%E8%B0%B7%E5%BA%97/@35.6563044,139.6986873,17z/data=!3m1!4b1!4m5!3m4!1s0x60188b5440ad5c93:0xa2dd6ed95050aea3!8m2!3d35.6563001!4d139.700876', 'https://tabelog.com/tokyo/A1303/A130301/13225241/', 'https://gf5j603.gorp.jp/', 2, 2, 0, 1);
INSERT INTO public.bars (id, created_at, updated_at, name, location, lat, lon, type, points, experience, visited, visit_date, google_maps_link, tabelog_link, official_website, score, score_place, score_mingling, score_price) VALUES (12, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Rock no cocoro', 'Shibuya, Udagawacho', 35.662463, 139.696944, 'Bar', 'Loud rock music. Quite narrow, but pretty nice atmosphere.', 'Quite loud, it is difficult to have a conversation. Can be smoky too. If not too crowded, it is possible to play darts. If you enjoy the music, atmosphere is quite nice, and the crowd usually as well. Prices are alright (like 600 yen for a glass of wine).', true, '2017-07-07 22:00:00', 'https://www.google.com/maps/place/%E3%83%AD%E3%83%83%E3%82%AF%E3%81%AE%E3%81%93%E3%81%93%E3%82%8D+rock+no+cocoro/@35.6624971,139.6948316,17z/data=!3m1!4b1!4m5!3m4!1s0x60188ca94e710061:0xaaa1b5c22d19ddd3!8m2!3d35.6624928!4d139.6970203', 'https://tabelog.com/tokyo/A1303/A130301/13096097/', 'http://www.rocknococoro.com/home.html', 1, 1, 2, 1);
INSERT INTO public.bars (id, created_at, updated_at, name, location, lat, lon, type, points, experience, visited, visit_date, google_maps_link, tabelog_link, official_website, score, score_place, score_mingling, score_price) VALUES (13, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'JBS', 'Shibuya', 35.657019, 139.696739, 'Music Bar', 'Small music bar. No smoking. Scary bartender. Great music, not too loud. No table charge. Cheap drinks. No food.', 'This place is very unique. First thing you notice, is the very nice room, all wood, and thousands and thousands of vynils. Then you notice the bartender is an old Japanese man who looks extremely angry and unfriendly. You will not feel welcomed. If you ask him if there is a menu, or if you can smoke, or he has Japanese sake, he will just get angry at you. It is seriously unbelievable, especially in Japan. But, if you can ignore this, then you can have a great time. Just ask for a drink based on what bottles you see at the bar. It will be 500 yen for a whiskey or a simple cocktail like a vodka tonic, or a bottled beer. There is no charge. No food. The music, and the accoustic, is really great. The volume was perfect to me, loud enough to enjoy the music, but without hurting your ears, and there is no problem having a conversation without speaking loudly. Actually, try not being loud, that would make the owner even angrier.', true, '2019-03-20 22:00:00', 'https://www.google.com/maps/place/Jazz+Blues+Soul+Bar/@35.6570326,139.6945271,17z/data=!3m1!4b1!4m5!3m4!1s0x60188b560d4a3e8d:0x38273669398e2e25!8m2!3d35.6570283!4d139.6967158', 'https://tabelog.com/tokyo/A1303/A130301/13123950/', 'https://eyescream.jp/fashion/1608/', 2, 2, 1, 1);
INSERT INTO public.bars (id, created_at, updated_at, name, location, lat, lon, type, points, experience, visited, visit_date, google_maps_link, tabelog_link, official_website, score, score_place, score_mingling, score_price) VALUES (14, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Tokyo Wine Club Raku', 'Shibuya', 35.657538, 139.697765, 'Izakaya', 'Nice and lively place. Good to enjoy some unexpensive wine. 500 yen otoshi.', 'The place was quite crowded, but with a very nice and lively atmosphere. Nice staff. Terrace with a few tables available outside too. Wine is not expensive, starting at 2800 yen a bottle, with lots of options. You will have to accept a small salad that costs 500 yen in order to stay. They offer a lots of small dishes to accompany wine, as well.', true, '2019-03-20 22:00:00', 'https://www.google.com/maps/place/%E6%9D%B1%E4%BA%AC%E3%83%AF%E3%82%A4%E3%83%B3%E5%80%B6%E6%A5%BD%E9%83%A8+%E6%A5%BD/@35.6577027,139.6965384,17.75z/data=!4m5!3m4!1s0x0:0x5bcac7d78f4ec076!8m2!3d35.6573443!4d139.6977125', 'https://tabelog.com/tokyo/A1303/A130301/13109931/', 'https://tokyowinecluberaku.gorp.jp/', 2, 2, 0, 1);
INSERT INTO public.bars (id, created_at, updated_at, name, location, lat, lon, type, points, experience, visited, visit_date, google_maps_link, tabelog_link, official_website, score, score_place, score_mingling, score_price) VALUES (15, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Tavern Bach', 'Shibuya', 35.657093, 139.697368, 'Izakaya', 'Feels like a very cheap izakaya, but actually not cheap.', 'Inside looks terrible. No decoration nor atmosphere whatsoever. It is just a big room with simple tables next to each other, with stools to seat. It is extremely bare. It feels cheap, but it is not. Prices are the same than a regular, nice izakaya. It gets crowded easily for some reasons though, so it can become noisy and smoky. There are tablets for placing orders but it is in Japanese only, without pictures, and the interface is crappy and not intuitive. It is possible to order from an English paper menu, despite the staff does not understand English. It takes longer but it is doable. The choice of food is not great, and the quality is not great either... I cannot see any reason to go there.', true, '2019-03-20 22:00:00', 'https://www.google.com/maps/place/Tavern+Bach/@35.6571329,139.6967588,18.5z/data=!4m5!3m4!1s0x60188b566b2f02bf:0x122b10ce3fa1163a!8m2!3d35.6570919!4d139.6973728', 'https://tabelog.com/tokyo/A1303/A130301/13182198/', 'https://www.hotpepper.jp/strJ001127934/yoyaku/?vos=othpporgzzzzx00000001', 0, 0, 0, 1);
