INSERT INTO public.karaokes (id, created_at, updated_at, name, area, location, lat, lon, points, experience, visited, visit_date, google_maps_link, official_website, score) VALUES (1, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Karaoke-kan', 'Shibuya', 'Center Gai', 35.660434, 139.698699, 'Biggest karaoke chain in Tokyo, but not the cheapest.', 'Situated in the main street "center gai", the place always look quite busy. Most Karaokekan offers maracas and tambourines to play with for free, as well as some costumes. Of course, lots of drinks and food are also available on the menu, with all-you-can-drink options.', false, NULL, 'https://www.google.com/maps/place/Karaokekan/@35.6582333,139.6973818,17z/data=!4m5!3m4!1s0x60188ca9a62ec5c7:0xe9b5b3ca3ef50590!8m2!3d35.660417!4d139.698798', 'http://karaokekan.jp/index.html', 1);
INSERT INTO public.karaokes (id, created_at, updated_at, name, area, location, lat, lon, points, experience, visited, visit_date, google_maps_link, official_website, score) VALUES (2, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Joysound', 'Shibuya', 'Sation''s south exit', 35.6584, 139.699813, 'One of the main systems maker', 'Good karaoke with popular system. If the main building is full, they will take you to some other subsidiary place nearby.', false, NULL, 'https://www.google.com/maps/place/JOYSOUND/@35.6590358,139.6999694,18z/data=!4m8!1m2!2m1!1sjoysound!3m4!1s0x60188b57c0c20b7b:0x2daf0687b41f13ca!8m2!3d35.6583445!4d139.6998317', 'https://shop.joysound.com/shop/joysound-shibuyaminamiguchi/', 1);
INSERT INTO public.karaokes (id, created_at, updated_at, name, area, location, lat, lon, points, experience, visited, visit_date, google_maps_link, official_website, score) VALUES (3, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Joysound', 'Shibuya', 'Dogenzaka', 35.657687, 139.698939, 'One of the main systems maker', 'Good karaoke with popular system.', false, NULL, 'https://www.google.com/maps/place/%E3%82%AB%E3%83%A9%E3%82%AA%E3%82%B1+JOYSOUND%E6%B8%8B%E8%B0%B7%E9%81%93%E7%8E%84%E5%9D%82%E5%BA%97%EF%BC%88%E3%82%B8%E3%83%A7%E3%82%A4%E3%82%B5%E3%82%A6%E3%83%B3%E3%83%89%EF%BC%89/@35.6578705,139.6981214,18z/data=!4m8!1m2!2m1!1sjoysound!3m4!1s0x60188b57b4dc951b:0x11d4e65747f637eb!8m2!3d35.6576613!4d139.6988554', 'https://shop.joysound.com/shop/joysound-shibuyadougenzaka/', 1);
INSERT INTO public.karaokes (id, created_at, updated_at, name, area, location, lat, lon, points, experience, visited, visit_date, google_maps_link, official_website, score) VALUES (4, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Uta hiroba', 'Shibuya, Udagawacho', 'Center Gai', 35.660288, 139.698565, 'Probably the cheapest karaoke chain', 'Cheap, especially if you want drinks. Rooms are okay, but far from the greatest.', true, NULL, 'https://www.google.com/maps/place/Utahiroba/@35.6602727,139.6967805,17z/data=!3m1!4b1!4m5!3m4!1s0x60188ca9b444643b:0x6e3a4892d8daafed!8m2!3d35.660269!4d139.698621', 'http://www.utahiro.com/', 1);
