INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (1, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Yamada Denki LABI', 'Shibuya', 35.658545, 139.698468, 'Electronics', 'Big store with lots of appliances, audio and video electronics, phones, cameras and games.', 'Spacious store, comfortable shopping, lots of choices.', 'https://www.google.com/maps/place/Yamada+Denki+LABI/@35.6598002,139.6970517,18z/data=!3m2!4b1!5s0x60188ca9c7f11c9d:0x1426b2054802885b!4m5!3m4!1s0x60188ca9c8780fb7:0x9ca8fa1cb4dd1218!8m2!3d35.659798!4d139.698146', 'http://www.yamadalabi.com/shibuya/', 3);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (2, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Asics Flagship', 'Harajuku', 35.670367, 139.706605, 'Sports', 'Japanese sports wear. Specialized in sneakers using gel technology.', 'Spacious store, comfortable shopping. Great Japanese sneakers. Sizes up to 32cm.', 'https://www.google.com/maps/place/ASICS+Harajuku+Flagship+Store/@35.6699328,139.7036335,17z/data=!4m8!1m2!2m1!1sAsics!3m4!1s0x60188ca4fac54abd:0xdac77910b1a5d314!8m2!3d35.6703773!4d139.7066161', 'https://www.asics.com/jp/ja-jp/store/AJP-A09014A/%E3%82%A2%E3%82%B7%E3%83%83%E3%82%AF%E3%82%B9%E5%8E%9F%E5%AE%BF%E3%83%95%E3%83%A9%E3%83%83%E3%82%B0%E3%82%B7%E3%83%83%E3%83%97', 3);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (3, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Shibuya109', 'Shibuya', 35.659551, 139.698904, 'Fashion', 'The famous 109. Fashion for girls.', 'Multitude of small fashion stores for girls.', 'https://www.google.com/maps/place/109/@35.6595752,139.696562,17z/data=!3m2!4b1!5s0x60188ca9cd4c44b5:0xc538795a27b68b27!4m5!3m4!1s0x60188ca9cd6c1c87:0x55a2a75ba417e072!8m2!3d35.6595709!4d139.6987507', 'https://www.shibuya109.jp', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (4, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Magnet by Shibuya109', 'Shibuya', 35.659702, 139.700843, 'Fashion', 'Previously called 109men. Small shops mostly for young men''s fashion.', 'Interesting styles, targets (very) young Japanese guys with trendy clothes and accessories. Employees are quite pushy. Not easy to find a fitting size for foreigners. Some restaurants on 7F, and an access to the rooof top, with a nice view, where it is possible to have your picture taken from way above so you appear with the legendary crossing below.', 'https://www.google.com/maps/place/Magnet+by+Shibuya+109/@35.6583877,139.7002794,18z/data=!4m5!3m4!1s0x0:0x6c103e05d0fa17a7!8m2!3d35.6597803!4d139.7009392', 'https://www.shibuya109.jp/MAGNET/', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (5, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Asics Tiger', 'Shibuya', 35.661466, 139.700333, 'Shoes', 'Nice small shop for this cool Japanese sports brand. Great sneakers and some clothes. Style between Onitsuka and Asics.', 'Very nice. Friendly staff (English OK). Size up to 31cm.', 'https://www.google.com/maps/place/%E3%82%A2%E3%82%B7%E3%83%83%E3%82%AF%E3%82%B9%E3%82%BF%E3%82%A4%E3%82%AC%E3%83%BC%E6%B8%8B%E8%B0%B7(ASICSTIGER+SHIBUYA)/@35.6605018,139.7001443,18z/data=!4m5!3m4!1s0x60188ca8669cf941:0x62b0ed59c5df6ea2!8m2!3d35.6614803!4d139.7003428', 'https://www.asicstiger.com/jp/ja-jp/store/asicstiger-shibuya', 3);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (6, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Onitsuka Tiger', 'Shibuya', 35.66139, 139.700407, 'Shoes', 'Nice small shop for this cool Japanese sports brand. Great sneakers and some clothes.', 'Very nice. Friendly staff (English OK). Size up to 31cm. Don''t forget to visit the second floor as well.', 'https://www.google.com/maps/place/Onitsuka+Tiger+Shibuya/@35.6605388,139.7003651,18z/data=!4m5!3m4!1s0x60188ca864760f11:0x3496cc8b96beb28f!8m2!3d35.6613909!4d139.7004107', 'https://www.onitsukatiger.com/jp/ja-jp', 3);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (7, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Adidas', 'Shibuya', 35.659762, 139.699253, 'Sports', 'Adidas "Brand Core" store. Nice but possibly pricey sneakers on the first floor. 2 upper floors of sports wear for men and women.', 'Nice staff. Size for shoes goes up to 30cm, maybe 30.5cm on some models. Slightly more expensive than other similar brands.', 'https://www.google.com/maps/place/adidas+Brand+Core+Store+Shibuya/@35.6587902,139.6979947,18z/data=!4m8!1m2!2m1!1sadidas!3m4!1s0x60188ca82fd3a799:0x421320b45b1ea565!8m2!3d35.6597771!4d139.6992642', 'https://shop.adidas.jp/', 2);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (8, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Under Armor', 'Shibuya', 35.659352, 139.699383, 'Sports', 'Under Armor flagship. Nice sneakers on the first floor. 2 upper floors of sports wear for men and women.', 'Kind of small room on the 1st floor for sneakers. Size for shoes goes up to 30cm.', 'https://www.google.com/maps/place/Under+Armour+ClubHouse+Shibuya/@35.6589411,139.698767,18z/data=!4m12!1m6!3m5!1s0x60188ca82873f91d:0x383fe154199e264a!2sUnder+Armour+ClubHouse+Shibuya!8m2!3d35.6593203!4d139.6993785!3m4!1s0x60188ca82873f91d:0x383fe154199e264a!8m2!3d35.6593203!4d139.6993785', 'https://www.underarmour.co.jp/ja-jp/shibuya.php', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (9, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'ABC Mart', 'Shibuya', 35.660326, 139.698601, 'Shoes', 'Various sneakers from popular brands.', 'Gives an easy and nice overview of main sneakers brand''s models. Sizes go up to 30cm on some (rare) models.', 'https://www.google.com/maps/place/ABC-MART+Grand+Stage+%E6%B8%8B%E8%B0%B7%E5%BA%97%EF%BB%BF/@35.6594121,139.6982193,18z/data=!4m5!3m4!1s0x60188ca9b45e6a51:0x48c45a8dbc85b19a!8m2!3d35.660238!4d139.698576', 'https://www.abc-mart.net/shop/', 2);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (10, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Asics Walking', 'Shibuya', 35.66013, 139.705131, 'Shoes', 'Dress shoes from Asics (Japanese sneakers brand).', 'Small shop selling dress shoes for men and woman. Leather, and more casual models as well. Most models go up to 28cm, some up to 30cm.', 'https://www.google.com/maps/place/%E3%82%A2%E3%82%B7%E3%83%83%E3%82%AF%E3%82%B9%E3%82%A6%E3%82%A9%E3%83%BC%E3%82%AD%E3%83%B3%E3%82%B0+%E6%B8%8B%E8%B0%B7/@35.6586334,139.7018858,17z/data=!4m8!1m2!2m1!1sasics!3m4!1s0x0:0xea2cf1b0e6c971b!8m2!3d35.6602551!4d139.7050811', 'https://www.asics.com/jp/ja-jp/walking', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (11, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Glitter', 'Shibuya', 35.660181, 139.70535, 'Shoes', 'Small shoe shop', 'Dress shoes, and more casual models as well. Sizes up to 28cm.', 'https://www.google.com/maps/place/glitter+%E6%B8%8B%E8%B0%B7%E5%BA%97/@35.6588939,139.7010323,17z/data=!4m5!3m4!1s0x60188b58c3d5573f:0x98707c0809e40e8f!8m2!3d35.6601753!4d139.7053399', 'http://www.mar-c.jp/shop/shop_glitter/326/', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (12, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Western Arms', 'Shibuya', 35.660206, 139.70545, 'Airsoft guns', 'Airsoft guns, replicas from anime, movies and military.', 'Those replicas look nice. Mostly handguns, some rifles as well. Prices range mostly betweeen 30 and 45 thousand yen.', 'https://www.google.com/maps/place/Western+Arms/@35.6596055,139.7037567,17z/data=!4m5!3m4!1s0x60188b58c16a7a17:0x10bb05fd1d6dfe91!8m2!3d35.6602002!4d139.7054408', 'http://www.wa-gunnet.co.jp/', 2);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (13, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Tokyu', 'Shibuya', 35.658762, 139.700833, 'Mall', 'Mall merged with the Shibuya train station.', 'Multitudes of shops. Convenient in case of bad weather because no need to get out from the station. Rather nice food section at the basement floors. Restaurants at the 9th floor.', 'https://www.google.com/maps/place/Tokyu+Department+Store/@35.6587263,139.6986498,17z/data=!3m2!4b1!5s0x60188b59c00ac46b:0x89a02b538fc1dabb!4m5!3m4!1s0x60188b5818bf6c25:0xaa2d6c840dc985b9!8m2!3d35.658722!4d139.7008385', 'https://www.tokyu-dept.co.jp/toyoko/', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (14, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Yamaya', 'Shibuya', 35.657499, 139.69574, 'World liquor', 'Lots of Japanese and imported beverages. Some snacks, sweet, and other imported condiments as well.', 'Yamaya is a chain of stores selling mostly alcohol, but also a lot of imported beverages and condiments. This Yamaya is probably the most spacious I know. Very nice shopping there. They have tons of sake, wine, whiskey, beers, and many other stuff. Prices are quiet good as well. Common drinks are actually cheaper than combini or even supermarkets. It is a good place if you are looking for a nice bottle or some gifts. They provide with delivery service as well.', 'https://www.google.com/maps/place/Yamaya+Dogenzaka/@35.6576688,139.6976373,17z/data=!4m8!1m2!2m1!1syamaya!3m4!1s0x0:0x122e5af592861839!8m2!3d35.6575447!4d139.6955234', 'https://www.yamaya.jp/pages/store/store/413dougenn.html', 2);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (15, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'B&D', 'Shibuya', 35.658336, 139.703584, 'Sports', 'Nice and relatively large sports shop.', 'Nice shop with a wide choice of sneakers from different brands, and equipement to test and help you to get the best fit for your feet. Also sells cloths, gears, protein packs...', 'https://www.google.com/maps/place/B%26D/@35.658425,139.7013473,17z/data=!3m1!4b1!4m5!3m4!1s0x60188b59ac933b79:0x31446d6ad3a599b!8m2!3d35.658425!4d139.703536', 'https://www.bnd.co.jp/shop_detail/sibuya', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (16, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Daiso', 'Shibuya', 35.661462, 139.697177, '100yen shop', 'All items are sold for 100 yen (+tax), and there is a lot of stuff.', 'Impressive choice of various items (gifts, housewares, snacks...) for 100 yen. 2 floors. A great place to find unexpensive souvenirs as well, as many things are very "Japanese".', 'https://www.google.com/maps/place/DAISO/@35.6614889,139.6949319,17z/data=!3m1!4b1!4m5!3m4!1s0x60188ca95fa1a9bd:0xaf5537d8a7346f7f!8m2!3d35.6614846!4d139.6971206', 'https://www.daiso-sangyo.co.jp/shop/detail/8931', 3);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (17, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Can Do', 'Shibuya', 35.66177, 139.697603, '100yen shop', 'All items are sold for 100 yen (+tax), and there is a lot of stuff.', 'Impressive choice of various items (gifts, housewares, snacks...) for 100 yen. A great place to find unexpensive souvenirs as well, as many things are very "Japanese". A bit less narrow and less crowded than Daiso.', 'https://www.google.com/maps/place/Can+Do+Shibuya+Inokashira-dori/@35.6617661,139.6954257,17z/data=!3m1!4b1!4m5!3m4!1s0x60188ca96addf449:0x913ed7631d16f53c!8m2!3d35.6617618!4d139.6976144', 'https://www.cando-web.co.jp/', 2);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (18, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Tokyu Hands', 'Shibuya, Udagawacho', 35.662, 139.697741, 'Creative Gifts', 'Big store offering an enormous variety of gifts, craft and... lots of stuff.', 'Nice and big, with a somewhat confusing floors system. Can find some great things in there, but be ready to pay a relatively high price.
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (19, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Janpara', 'Shibuya, Dogenzaka', 35.658948, 139.697916, 'Used Electronics', 'Small shop. Buy and sell second hand smartphones and electronics..', 'Interesting choice of second hand stuff such as laptops, smartphones, some heaphones, video games consoles or video cameras...', 'https://www.google.com/maps/place/%E3%81%98%E3%82%83%E3%82%93%E3%81%B1%E3%82%89+%E6%B8%8B%E8%B0%B7%E9%81%93%E7%8E%84%E5%9D%82%E5%BA%97/@35.6589056,139.6957593,17z/data=!3m1!4b1!4m5!3m4!1s0x60188ca9d964652b:0xae9c85f47e4cae05!8m2!3d35.6589013!4d139.697948', 'http://www.janpara.co.jp/', 2);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (20, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Janpara', 'Shibuya, Udagawa', 35.661688, 139.697853, 'Used Electronics', 'Small shop, on 2 floors. Buy and sell second hand smartphones and electronics.', 'Interesting choice of second hand stuff such as laptops, smartphones, some heaphones, video games consoles or video cameras...', 'https://www.google.com/maps/place/Jun-Para+Shibuya+Udagawa/@35.6605314,139.6963436,16.75z/data=!4m5!3m4!1s0x60188ca90a37c15f:0xdecb0d4d9500cb3f!8m2!3d35.661687!4d139.6978643', 'http://www.janpara.co.jp/', 2);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (29, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Technique', 'Shibuya, Udagawacho', 35.660924, 139.697028, 'Records', 'Great for electronic music on vinyl.', 'Highly specialized in house, dance, and any kind of electronic music. Small, but nice shop, where you can even have a beer, and check out flyers for upcoming DJ event in town.', 'https://www.google.com/maps/place/TECHNIQUE/@35.6609314,139.6948219,17z/data=!3m1!4b1!4m5!3m4!1s0x60188ca970e7aaab:0xbc1e41d88c7706d6!8m2!3d35.6609271!4d139.6970106', 'https://technique.co.jp/', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (30, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Manhattan Records', 'Shibuya, Udagawacho', 35.662505, 139.69688, 'Records', 'Awesome for rap and hip-hop.', 'Higly specilized in rap and hip-hop, with lots of American and Japanese vinyls, old and new.', 'https://www.google.com/maps/place/Manhattan+Records/@35.6625155,139.6947012,17z/data=!3m1!4b1!4m5!3m4!1s0x60188ca94e710061:0x1d13fad0be6bdbfb!8m2!3d35.6625112!4d139.6968899', 'http://manhattanrecords.jp/', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (31, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Disc Union Shibuya', 'Shibuya, Udagawacho', 35.660934, 139.698086, 'Records', 'Very popular store for music and vinyls discs.', 'This store often appears in the world''s top 10 best record shops... The first two floors have tons of used vinyl discs of every kind. Then going up there is dance and hip hop, and up again for punk, hardcore and heavy metal. In the basement is where you’ll find the some rare groove, soul and jazz. If you are a music enthusiast looking for rarities, this is a very exiting place.', 'https://www.google.com/maps/place/Disk+Union+Record+Vinyl+Store/@35.6608982,139.6958764,17z/data=!3m1!4b1!4m5!3m4!1s0x60188ca9a7bb87cd:0x116297446f5495a9!8m2!3d35.6608939!4d139.6980651', 'http://diskunion.net/', 2);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (21, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Mark City', 'Shibuya, station', 35.658766, 139.699672, 'Mall', 'Big mall attached to Shibuya station.', 'Generally opened from 10am to 9pm. The mall might be tricky because of its first 3 floors are separated in 2 different buildings, the west and east malls. You might really need to <a target="blank" href="http://www.s-markcity.co.jp/foreign/floormap.html">lookup the map</a>.
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (22, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Seibu', 'Shibuya, Seibu', 35.660118, 139.700556, 'Mall', 'Big spacious mall with multitudes of small luxury shops.', 'Not crowded. Spacious, with many luxury fashion brands. Prices starts at about 10 thousand yen for the simplest white T-Shirt. The mall is divided in 2 buildings called A and B, that connects to each other on some floors. You can connect to their free wifi using the password "seibu123". Tax free service is available at A 7F.
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (23, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Hikarie ShinQs', 'Shibuya, Hikarie', 35.658929, 139.703265, 'Mall', 'Fancy mall, connected to Shibuya station.', 'Nice things. No need to go outside from the station to get there. Can get a nice view from higher floor.
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (24, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Tokyu Honten', 'Shibuya, Bunkamura', 35.66064, 139.696345, 'Mall', 'Tokyu main department store. Luxury stuff.', 'Big spacious department store. Mostly luxury fashion and goods.', 'https://www.google.com/maps/place/Tokyu+Honten/@35.6606425,139.6938291,17z/data=!3m2!4b1!5s0x60188cabd76c1a77:0xea9b2a49da49661e!4m5!3m4!1s0x60188cabdc972d2f:0x7e09efa541645aa5!8m2!3d35.6606382!4d139.6960178', 'https://www.tokyu-dept.co.jp/honten/', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (25, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Lighthouse Records', 'Shibuya', 35.658782, 139.69832, 'Records', 'Cool shop, great for electronic and house music.', 'Very easy to miss from the street, but very nice shop. Great selection of electronic music, nu disco and house.', 'https://www.google.com/maps/place/Lighthouse+Records/@35.6581766,139.6970925,17.25z/data=!4m5!3m4!1s0x60188b56282f48a7:0x34eb8d132bc55332!8m2!3d35.658761!4d139.698286', 'http://lighthouserecords.jp/', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (26, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'HMV Record Shop', 'Shibuya, Udagawacho', 35.662127, 139.697295, 'Records', 'Big chain of records shops.', 'Big chain, selling new and second hand music of all genre. Seems good to find some Japanese independant pop or some soul and jazz imports. Also sells some turntables, some CDs, DVDs, and books. The shop is spacious enough for comfortable shopping.', 'https://www.google.com/maps/place/HMV+record+shop+Shibuya/@35.6617985,139.6954999,17.25z/data=!4m5!3m4!1s0x60188ca9415924a3:0x81eea8f480cb05d5!8m2!3d35.6620243!4d139.6972123', 'http://recordshop.hmv.co.jp/', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (27, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Face Records', 'Shibuya, Udagawacho', 35.662674, 139.697147, 'Records', 'Great for soul, jazz and reggae on vinyl', 'Great atmosphere. Sells vinyls, but also some CDs, DVDs, and books.', 'https://www.google.com/maps/place/Face+Record/@35.66268,139.6949487,17z/data=!3m1!4b1!4m5!3m4!1s0x60188cac07d0dd05:0x7aba033eb37ed2ce!8m2!3d35.6626757!4d139.6971374', 'http://www.facerecords.com/', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (28, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Next Records', 'Shibuya, Udagawacho', 35.66257, 139.697193, 'Records', 'Vinyls for funk, disco, dance or RnB.', 'Always up to date when it comes to funk, disco, dance or RnB, with imports from Europe and U.S.A. No bootlegs. About 10,000 original 12" singles. Also selling some second hand Technics turntables (and a DJ equipment shop is next door).', 'https://www.google.com/maps/place/next+records/@35.6625535,139.6950264,17z/data=!3m1!4b1!4m5!3m4!1s0x60188ca94de4afa3:0x5436e42f3cf7da0!8m2!3d35.6625492!4d139.6972151', 'http://www.nextrecordsjapan.net/for-foreign-visitor.html', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (32, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Tower Records Shibuya', 'Shibuya, Jinnan', 35.661911, 139.700972, 'Records', 'Biggest records store in Japan.', '7 floors, selling mostly CDs, for all kind of music. Big, peculiar building, with another statue of Hachiko at its feet, it makes for another popular meeting points for young people.', 'https://www.google.com/maps/place/Tower+Records+Shibuya/@35.6619233,139.6988062,17z/data=!3m1!4b1!4m5!3m4!1s0x60188ca87eba86d5:0xc878b2fe3fed54f0!8m2!3d35.661919!4d139.7009949', 'http://tower.jp/', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (33, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Mont-Bell', 'Shibuya, Udagawacho', 35.662339, 139.697618, 'Outdoor', 'Big store selling all kind of outdoor clothes and gear.', 'Spacious and nice, it provides a relaxing shopping experience. There are a lot of clothes and gear for moutains, snow, and cycling. Mont-Bell is a Japanese brand, making high quality stuff and selling them slightly cheaper than big names such as The North Face. There is an English version of their website here: <a href="https://en.montbell.jp/">https://en.montbell.jp/.</a>.
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (34, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Function Junction', 'Shibuya, Udagawacho', 35.662035, 139.697575, 'Outdoor', 'Small shop, cool outdoor clothes and gear.', 'Small shop, very nice staff. Selling high quality, expensive clothes and gears from various brands. There are also some Tokyo souvenirs T-shirts and whatnot.', 'https://www.google.com/maps/place/FUNCTION+JUNCTION+TOKYO/@35.6614306,139.6964239,17z/data=!4m5!3m4!1s0x60188ca93fbd2021:0xdd16ce3769b16d28!8m2!3d35.6620372!4d139.6975833', 'http://www.functionjunctiontokyo.com/', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (35, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'A&F Country', 'Shibuya, Hikarie', 35.659258, 139.70402, 'Outdoor', 'Nice outdoor shop inside the Hikarie building.', 'Nice shop at the 4th floor of Hikarie. Helpful staff. Selling high quality brand, such as Outdoor Research. Also in the same alley with small shops for The North Face and Sora, which is selling Patagonia.', 'https://www.google.com/maps/place/A%26F%E3%82%AB%E3%83%B3%E3%83%88%E3%83%AA%E3%83%BC+%E6%B8%8B%E8%B0%B7%E3%83%92%E3%82%AB%E3%83%AA%E3%82%A8ShinQs%E5%BA%97/@35.6591053,139.7015284,16.75z/data=!3m1!5s0x60188b58f894f891:0x4ceb5b05e50a8109!4m5!3m4!1s0x60188b58f9ad804b:0x8ca51d84e75fc700!8m2!3d35.6592766!4d139.7040703', 'https://www.aandf.co.jp/stores/afcountry/shibuya_hikarie', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (36, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Ikebe Digital Tower', 'Shibuya', 35.65683, 139.700697, 'Music gear', 'Sells and show stuff for DJs and home studio, keyboards and pianos.', 'Crappy, easy to miss entrance in a back street, but this is a nice shop with a lot of stuff you can see and try.
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (37, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Zoff', 'Shibuya, Mark City', 35.657738, 139.69736, 'Glasses', 'Decent choice, nice prices.', 'Decent choice of glasses and some sunglasses as well. Prices range from 5 to 30 thousand yen.', 'https://www.google.com/maps/place/Zoff+%E6%B8%8B%E8%B0%B7%E3%83%9E%E3%83%BC%E3%82%AF%E3%82%B7%E3%83%86%E3%82%A3%E5%BA%97/@35.6578426,139.6965479,17.5z/data=!3m1!5s0x60188b5631f5f4af:0xf2c804907c6b11f9!4m5!3m4!1s0x60188b560f5d27e3:0x24a4d2c31e8cc1e8!8m2!3d35.6577383!4d139.6973389', 'https://www.zoff.co.jp/shop/store/11006', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (38, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Zoff', 'Shibuya, Center Gai', 35.660804, 139.697525, 'Glasses', 'Decent choice, nice prices.', 'Decent choice of glasses and some sunglasses as well. Prices range from 5 to 30 thousand yen. This store is bigger than the one in Mark City.', 'https://www.google.com/maps/place/Zoff+%E3%82%B0%E3%83%A9%E3%83%B3%E3%83%89%E6%9D%B1%E4%BA%AC%E6%B8%8B%E8%B0%B7%E5%BA%97/@35.6601384,139.6952022,17.25z/data=!4m5!3m4!1s0x60188d6daa575853:0x192eb2eb0b363826!8m2!3d35.660804!4d139.6974263', 'https://www.zoff.co.jp/shop/store/11273', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (39, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Washin Optical Shibuya', 'Shibuya, Udagawacho', 35.659868, 139.698984, 'Glasses', 'Lots of choice, can be pricey.', 'Lots of choice, can be pricey. Nice shop.', 'https://www.google.com/maps/place/WASHIN+OPTICAL+SHIBUYA/@35.6599246,139.6969207,17z/data=!3m1!4b1!4m5!3m4!1s0x60188ca833e2f497:0xd9d9ef6495cf3f8a!8m2!3d35.6599246!4d139.6991094', 'https://www.washin-optical.co.jp/', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (40, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Megane Ichiba', 'Shibuya, Udagawacho', 35.660889, 139.700693, 'Glasses', 'Very decent choice, some sunglasses, decent prices.', 'There are 2 floors. A lot more choices are on the 2nd floor. Prices are like 20 or 30 thousand yen.', 'https://www.google.com/maps/place/Megane+Ichiba/@35.6608763,139.6984219,17z/data=!3m1!4b1!4m5!3m4!1s0x60188ca812d3604d:0x6b0f0c3e3ad9299!8m2!3d35.6608763!4d139.7006106', 'https://www.meganeichiba.jp/', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (41, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Owndays', 'Shibuya, Mark City', 35.658576, 139.699308, 'Glasses', 'Very small, very little choice.', 'Very small, very little choice. Some glasses from Rayban. Situated on the ground floor of Mark City.', 'https://www.google.com/maps/place/OWNDAYS+%E6%B8%8B%E8%B0%B7%E3%83%9E%E3%83%BC%E3%82%AF%E3%82%B7%E3%83%86%E3%82%A3%E5%BA%97/@35.6585808,139.697107,17z/data=!3m2!4b1!5s0x60188b5631c5f5a9:0xf2c804904456f99b!4m5!3m4!1s0x60188b57cdd3837d:0xb37fd1e3ab97907e!8m2!3d35.6585808!4d139.6992957', 'https://www.owndays.com/jp/ja/shops/687', 0);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (42, '2026-11-16 12:47:38', '2026-11-16 12:47:38', '999.9', 'Shibuya, Jinnan', 35.661781, 139.69992, 'Glasses', 'Decent but rather small, with some glasses and sunglasses.', 'Decent small store for the brand "Four nines", with limited choices of glasses and sunglasses.', 'https://www.google.com/maps/place/Four+Nines/@35.661782,139.6977373,17z/data=!3m1!4b1!4m5!3m4!1s0x60188ca8f4e4df61:0x7a511e3081efebd!8m2!3d35.661782!4d139.699926', 'http://www.fournines.co.jp/en/', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (43, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Eyewear Mebius', 'Shibuya, Jinnan', 35.66227, 139.699513, 'Glasses', 'Small shop with some models out of the ordinary.', 'Easy to miss, situated on 3 floor. Small shop, selling a German brand that has some interesting unique designs. Not so much choice though, and prices are rather high, like between 40 and 60 thousand yen.', 'https://www.google.com/maps/place/Eyewear+Mebius+%E6%B8%8B%E8%B0%B7/@35.6622188,139.6973623,17z/data=!3m1!4b1!4m5!3m4!1s0x60188ca8efc7cfff:0x6b206c380fa7cc21!8m2!3d35.6622188!4d139.699551', 'https://www.eyewearmebius.com/shop-info/', 0);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (44, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Megane Super', 'Shibuya, Udagawacho', 35.660958, 139.698069, 'Glasses', 'Small place with very limited choice.', 'Small place with very limited choice. Prices looked normal.', 'https://www.google.com/maps/place/MEGANE+SUPER+%E6%B8%8B%E8%B0%B7%E6%9C%AC%E5%BA%97/@35.6607043,139.6975889,18z/data=!4m5!3m4!1s0x60188d128d06cb4d:0xf53c7eeab8c8e2a9!8m2!3d35.6609309!4d139.698061', 'https://www.meganesuper.co.jp/shops/megane-super-%E6%B8%8B%E8%B0%B7%E6%9C%AC%E5%BA%97/', 0);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (45, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Klein', 'Shibuya, Udagawacho', 35.661403, 139.697093, 'Glasses', 'Small fashionable shop.', 'Fashionable, with limited choice, the prices seem to remain decent.', 'https://www.google.com/maps/place/KLEIN+EYEWEAR/@35.6601088,139.6967828,18z/data=!4m8!1m2!2m1!1z44Oh44Ks44ON!3m4!1s0x0:0x42c55ca99d5d5c82!8m2!3d35.6614421!4d139.6970368', 'https://klein-eyewear.com/', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (46, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'JINS', 'Shibuya, Udagawacho', 35.661676, 139.697662, 'Glasses', 'Decent choice, nice prices.', 'Decent choice of glasses and some sunglasses as well. Prices range from 5 to 30 thousand yen.', 'https://www.google.com/maps/place/JINS/@35.6604592,139.6972773,17.52z/data=!4m5!3m4!1s0x60188ca91368ded3:0x9e2c5d9dca932835!8m2!3d35.6616275!4d139.6976526', 'https://store-jp.jins.com/b/jins/info/20365/', 1);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (47, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Kaneko optical', 'Shibuya, Hikarie', 35.659028, 139.703465, 'Glasses', 'Rather small. Limited choice. Nothing cheap.', 'In the Hikarie building, 3rd floor, amongst other ShinQs shops. Rather small. Limited choice. Nothing cheap.', 'https://www.google.com/maps/place/Kaneko+Optical+Shop+(Shibuya+Hikarie+ShinQs)/@35.659058,139.7013144,17.26z/data=!4m5!3m4!1s0x60188bc1bebc7469:0xaa8325c092658e7c!8m2!3d35.6590249!4d139.703473', 'http://www.kaneko-optical.co.jp/jp/company/stores/kaneko.html', 0);
INSERT INTO public.stores (id, created_at, updated_at, name, location, lat, lon, type, points, experience, google_maps_link, official_website, score) VALUES (48, '2026-11-16 12:47:38', '2026-11-16 12:47:38', 'Ogura megane', 'Shibuya, 1Chome', 35.661262, 139.702103, 'Glasses', 'Large, upper class shop, decent choice.', 'Decent amount of choice, but mostly expensive (above 30,000 yen), with some Cartier above 100,000 yen.', 'https://www.google.com/maps/place/%E3%82%AA%E3%82%B0%E3%83%A9%E3%83%A1%E3%82%AC%E3%83%8D%E6%B8%8B%E8%B0%B7%E5%BA%97%E3%83%AD%E3%83%BC%E3%83%93%E3%82%B8%E3%83%A7%E3%83%B3%E3%82%BB%E3%83%B3%E3%82%BF%E3%83%BC/@35.6608694,139.7012906,18z/data=!4m5!3m4!1s0x60188ca7e88dec69:0xc43a610e32bae6b3!8m2!3d35.661266!4d139.702051', 'http://www.ogura-megane.co.jp/shop/5/', 1);
